package org.jlinalg.sequence;

import java.io.IOException;
import java.io.StringReader;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class HomerNamedTssTest {
    private static final Map<String,Long> REFERENCE=Map.of("chr1",1000L,"chr2",1000L);
    private static String row(String name,String chr,int point,char strand){return name+"\t"+chr+"\t"+(point-2000)+"\t"+(point+2000)+"\t"+(strand=='+'?0:1)+"\n";}
    private static HomerNamedTss.Dataset data(String text,boolean retain,boolean duplicates)throws Exception{return HomerNamedTss.read(new StringReader(text),REFERENCE,10000,10000,retain,duplicates,()->{});}
    private static HomerNamedFeatures.Query query(String id,int a,int b,char strand){return new HomerNamedFeatures.Query(id,"chr1",a,b,strand);}
    @Test void originalPlusMinusPromoterWindowsGiveExactAnchors()throws Exception{var d=data(row("plus","chr1",100,'+')+row("minus","chr1",300,'-'),false,false);assertEquals(List.of(100,300),d.records().stream().map(HomerNamedTss.Tss::position1).toList());var index=new HomerNamedTss.Index(d);assertTrue(index.nearest(query("q1",110,110,'+')).acceptsOriginal("plus",10));assertTrue(index.nearest(query("q2",310,310,'+')).acceptsOriginal("minus",-10));}
    @Test void queryStrandDoesNotChangeOriginalGeneOrientedDistance()throws Exception{var index=new HomerNamedTss.Index(data(row("gene","chr1",100,'-'),false,false));assertEquals(index.nearest(query("q",110,110,'+')),index.nearest(query("q",110,110,'-')));assertTrue(index.nearest(query("q",110,110,'-')).acceptsOriginal("gene",-10));}
    @Test void equidistantGenesRemainCompleteCompatibleFamily()throws Exception{var index=new HomerNamedTss.Index(data(row("left","chr1",100,'+')+row("right","chr1",120,'-'),false,false));var n=index.nearest(query("q",109,112,'+'));assertEquals(110,n.midpoint1());assertEquals(10,n.absoluteDistance());assertEquals(2,n.compatible().size());assertTrue(n.acceptsOriginal("left",10));assertTrue(n.acceptsOriginal("right",10));assertEquals(2,n.distinctOriginalAssignments());}
    @Test void firstHomerMarkerCollapseRetainsFullRawIdsAndNumericVersions()throws Exception{var d=data(row("NM_1.3","chr1",100,'+')+row("NM_1.3-HOMER2-other","chr1",120,'+'),false,false);assertEquals("NM_1.3-HOMER2-other",d.records().get(1).rawId());assertEquals("NM_1.3",d.records().get(1).originalPromoterId());assertEquals(1,d.collapsedOriginalIdGroups());assertEquals(1,d.reservedNameRows());var n=new HomerNamedTss.Index(d).nearest(query("q",110,110,'+'));assertTrue(n.acceptsOriginal("NM_1.3",10));assertTrue(n.acceptsOriginal("NM_1.3",-10));assertEquals(2,n.distinctOriginalAssignments());}
    @Test void collapsedRawTiesAreDistinctFromDistinctObservedAssignments()throws Exception{var d=data(row("gene","chr1",100,'+')+row("gene-HOMER1","chr1",100,'+'),false,false);var n=new HomerNamedTss.Index(d).nearest(query("q",105,105,'+'));assertEquals(2,n.compatible().size());assertEquals(1,n.distinctOriginalAssignments());assertThrows(UnsupportedOperationException.class,()->n.compatible().clear());}
    @Test void promoterWindowOverhangsAreNotInvalidatedWhenAnchorIsValid()throws Exception{var d=data(row("near-start","chr1",1,'+')+row("near-end","chr1",999,'-'),false,false);assertEquals(0,d.outOfReferenceAnchors());assertEquals(2,d.nonpositiveWindowStarts());assertEquals(2,d.windowEndOverruns());assertEquals(-1999,d.records().get(0).windowStart1());assertEquals(2999,d.records().get(1).windowEnd1());}
    @Test void invalidAnchorsNeedPermissionAndRemainUnclipped()throws Exception{String text=row("outside","chr1",2000,'+');assertThrows(IOException.class,()->data(text,false,false));var d=data(text,true,false);assertEquals(1,d.outOfReferenceAnchors());assertEquals(2000,d.records().get(0).position1());assertTrue(new HomerNamedTss.Index(d).nearest(query("q",1000,1000,'+')).acceptsOriginal("outside",-1000));}
    @Test void unknownResourceContigsAreRetainedOnlyUnderExplicitPolicy()throws Exception{String text=row("unknown","chrX",100,'+');assertThrows(IOException.class,()->data(text,false,false));var d=data(text,true,false);assertEquals(1,d.missingReferenceRecords());assertEquals(1,d.outOfReferenceAnchors());var n=new HomerNamedTss.Index(d).nearest(query("q",100,100,'+'));assertEquals(-1,n.absoluteDistance());assertTrue(n.compatible().isEmpty());}
    @Test void rawDuplicateIdsHaveTheirOwnExplicitRetentionAndSourceLastRowLookup()throws Exception{String text=row("same","chr1",100,'+')+row("same","chr1",120,'+');assertThrows(IOException.class,()->data(text,false,false));var d=data(text,false,true);assertEquals(2,d.records().size());assertEquals(1,d.duplicateRawIdRows());assertEquals(0,d.collapsedOriginalIdGroups());var index=new HomerNamedTss.Index(d);assertEquals(1,index.effectiveRecords());assertEquals(1,index.inactiveDuplicateRows());assertEquals(1,index.nearest(query("q",110,110,'+')).compatible().size());assertTrue(index.nearest(query("q",110,110,'+')).acceptsOriginal("same",-10));}
    @Test void resourceShapeAndSourceIntegerSafetyAreChecked(){for(String text:List.of("", "x\tchr1\t1\t4000\t0\n","x\tchr1\t1\t4001\t.\n","x\tchr1\t1\t4001\t0\textra\n","x\tchr1\t1073741820\t1073745820\t0\n","-HOMER1\tchr1\t-1900\t2100\t0\n"))assertThrows(Exception.class,()->data(text,true,true));}
    @Test void capacitiesAndDeadlineFailuresAreExplicit(){String text=row("a","chr1",100,'+')+row("b","chr1",120,'+');assertThrows(IOException.class,()->HomerNamedTss.read(new StringReader(text),REFERENCE,1,1000,false,false,()->{}));assertThrows(IOException.class,()->HomerNamedTss.read(new StringReader(row("x".repeat(100),"chr1",100,'+')),REFERENCE,10,32,false,false,()->{}));assertThrows(IOException.class,()->HomerNamedTss.read(new StringReader(text),REFERENCE,10,1000,false,false,()->{throw new IOException("deadline");}));}
    @Test void exactContigQueryBoundsAndFinalNonLfLineAreChecked()throws Exception{String text=row("gene","chr1",100,'+').stripTrailing();var d=data(text,false,false);var index=new HomerNamedTss.Index(d);assertEquals(1,d.records().size());assertTrue(index.nearest(query("q",100,100,'+')).acceptsOriginal("gene",0));assertThrows(IllegalArgumentException.class,()->index.nearest(query("q",1001,1001,'+')));assertThrows(IllegalArgumentException.class,()->index.nearest(new HomerNamedFeatures.Query("q","absent",1,10,'+')));}
}
